func (q *Queries) ListPaperSessionsOfUser(ctx context.Context, arg ListPaperSessionsOfUserParams) ([]ListPaperSessionsOfUserRow, error) {
	rows, err := q.db.QueryContext(ctx, listPaperSessionsOfUser, arg.OwnerUserID, arg.SubjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPaperSessionsOfUserRow{}
	for rows.Next() {
		var i ListPaperSessionsOfUserRow
		if err := rows.Scan(
			&i.ID,
			&i.PaperID,
			&i.Mode,
			&i.Status,
			&i.StartedAt,
			&i.SubmittedAt,
			&i.Score,
			&i.FullScore,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

