const qTypeScoreRates = `-- name: QTypeScoreRates :many
SELECT q.qtype, CAST(COALESCE(SUM(a.score), 0) AS DECIMAL(12,2)) AS got, CAST(COALESCE(SUM(a.full_score), 0) AS DECIMAL(12,2)) AS full
FROM attempts a JOIN questions q ON q.id = a.question_id
WHERE a.owner_user_id = ? AND a.score IS NOT NULL AND a.full_score IS NOT NULL
GROUP BY q.qtype
`

type QTypeScoreRatesRow struct {
	Qtype QuestionsQtype
	Got   string
	Full  string
}

// 用户各题型的平均得分率（估计时间失分，PRD 11.9）。
func (q *Queries) QTypeScoreRates(ctx context.Context, ownerUserID uint64) ([]QTypeScoreRatesRow, error) {
	rows, err := q.db.QueryContext(ctx, qTypeScoreRates, ownerUserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []QTypeScoreRatesRow{}
	for rows.Next() {
		var i QTypeScoreRatesRow
		if err := rows.Scan(&i.Qtype, &i.Got, &i.Full); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

